BEGIN
 IF lf_ops.nucleo_param_valor_v1('AUDIT.ONBOARDING_COMPLETED_LOG_RETENTION_DAYS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUDIT' AND config_key='ONBOARDING_COMPLETED_LOG_RETENTION_DAYS' AND hecho='ah_completed_days') THEN RAISE EXCEPTION 'S22AH_PARAM_PREFLIGHT AUDIT.ONBOARDING_COMPLETED_LOG_RETENTION_DAYS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('AUDIT.ONBOARDING_INCOMPLETE_LOG_RETENTION_DAYS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUDIT' AND config_key='ONBOARDING_INCOMPLETE_LOG_RETENTION_DAYS' AND hecho='ah_incomplete_days') THEN RAISE EXCEPTION 'S22AH_PARAM_PREFLIGHT AUDIT.ONBOARDING_INCOMPLETE_LOG_RETENTION_DAYS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('RATE_LIMIT.GATEWAY_PUBLIC_IP_REQUESTS_PER_MINUTE') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='RATE_LIMIT' AND config_key='GATEWAY_PUBLIC_IP_REQUESTS_PER_MINUTE' AND hecho='ah_public_rate') THEN RAISE EXCEPTION 'S22AH_PARAM_PREFLIGHT RATE_LIMIT.GATEWAY_PUBLIC_IP_REQUESTS_PER_MINUTE'; END IF;
 IF lf_ops.nucleo_param_valor_v1('RATE_LIMIT.GATEWAY_AUTH_JWT_REQUESTS_PER_MINUTE') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='RATE_LIMIT' AND config_key='GATEWAY_AUTH_JWT_REQUESTS_PER_MINUTE' AND hecho='ah_auth_rate') THEN RAISE EXCEPTION 'S22AH_PARAM_PREFLIGHT RATE_LIMIT.GATEWAY_AUTH_JWT_REQUESTS_PER_MINUTE'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AH_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AH_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AH_HASH_ALL %',hash_all;
END $ah$;
COMMIT;
